<script>
const DEMO_DATE = "2026-10-15";
const DAY = new Date(DEMO_DATE + "T12:00:00Z").getUTCDay();

const services = {
  "Wellness exam": {
    minutes: 30, price: "$65", restricted: false
  },
  "Vaccination visit": {
    minutes: 15, price: "$40", restricted: false
  },
  "Dental cleaning": {
    minutes: 90, price: "from $280", restricted: true, estimate: true
  },
  "Exotic pet check-up": {
    minutes: 45, price: "$85", restricted: true
  }
};
const vets = {
  "Mary Major": [2, 4, 6],
  "Richard Miles": [1, 2, 3, 4, 5, 6]
};
const rawSlots = [
  {"vet":"Richard Miles","service":"Exotic pet check-up","start":"10:00"},
  {"vet":"Mary Major","service":"Exotic pet check-up","start":"11:00"},
  {"vet":"Mary Major","service":"Dental cleaning","start":"11:30"},
  {"vet":"Richard Miles","service":"Wellness exam","start":"12:30"},
  {"vet":"Richard Miles","service":"Wellness exam","start":"14:00"},
  {"vet":"Mary Major","service":"Wellness exam","start":"16:45"}
];

const minutes = time => {
  if (!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(time)) return NaN;
  const [h, m] = time.split(":").map(Number);
  return h * 60 + m;
};
const clock = n =>
  String(Math.floor(n / 60)).padStart(2, "0") + ":" +
  String(n % 60).padStart(2, "0");
const qualifies = (vet, service) =>
  Boolean(vets[vet] && services[service]) &&
  (!services[service].restricted || vet === "Mary Major");

function bookable(slot) {
  const service = services[slot.service];
  if (!service || slot.date !== DEMO_DATE ||
      !qualifies(slot.vet, slot.service) ||
      !vets[slot.vet].includes(DAY)) return false;

  const start = minutes(slot.start);
  const end = start + service.minutes;
  // The ENTIRE appointment must fit in one open interval.
  return [[540, 720], [780, 1020]].some(
    ([open, close]) => start >= open && end <= close
  );
}

// Date assignment is a demo fixture, not information from the API.
const slots = rawSlots
  .map((slot, i) => ({...slot, id: String(i), date: DEMO_DATE}))
  .filter(bookable);

const state = { step: 0, service: "", vet: "any", slot: "" };
const $ = id => document.getElementById(id);
const selectedSlot = () => slots.find(slot => slot.id === state.slot);
const matching = (vet = state.vet) => slots.filter(slot =>
  slot.service === state.service &&
  (vet === "any" || slot.vet === vet)
);
const range = slot =>
  `${slot.start}–${clock(minutes(slot.start) + services[slot.service].minutes)}`;

function validSelection() {
  const slot = selectedSlot();
  return Boolean(slot && bookable(slot) &&
    slot.service === state.service &&
    (state.vet === "any" || slot.vet === state.vet));
}
function canContinue() {
  if (state.step === 0) return Boolean(state.service);
  if (state.step === 1) return Boolean(state.vet);
  if (state.step === 2) return validSelection();
  if (state.step === 3)
    return validSelection() && !services[state.service].estimate;
  return false;
}

function radio(name, value, checked, title, detail) {
  return `<label class="option">
    <input type="radio" name="${name}" value="${value}"
      ${checked ? "checked" : ""} required>
    <span><strong>${title}</strong><small>${detail}</small></span>
  </label>`;
}

function sync(announce = false) {
  const service = services[state.service];
  const slot = selectedSlot();
  $("sum-service").textContent = state.service || "Not selected";
  $("sum-price").textContent = service
    ? service.price + (service.estimate ? " — exact total required" : "")
    : "Not selected";
  $("sum-vet").textContent = slot ? `Dr. ${slot.vet}` :
    !service ? "Not selected" :
    state.vet === "any" ? "Any available vet — assigned with your time" :
    `Dr. ${state.vet}`;
  $("sum-time").textContent = slot ? `${range(slot)} (clinic-local)` :
    "Not selected";
  $("next").disabled = !canContinue();

  if (announce) {
    $("status").textContent =
      `Summary updated. ${$("sum-service").textContent}. ` +
      `Price: ${$("sum-price").textContent}. ` +
      `Vet: ${$("sum-vet").textContent}. ` +
      `Time: ${$("sum-time").textContent}.`;
  }
}

function render(focus = true) {
  const titles = [
    "Choose a service", "Choose a vet", "Choose a time",
    "Review & confirm", "Demo appointment confirmed"
  ];
  let body = "";

  if (state.step === 0) {
    body = `<p class="muted">Common visits first. Prices are shown before booking.</p>
      <fieldset><legend>Service and price</legend><div class="options">
      ${Object.entries(services).map(([name, service]) =>
        radio("service", name, state.service === name, name,
          `${service.minutes} min · ${service.price}` +
          (service.restricted ? " · Dr. Mary Major only" : ""))
      ).join("")}
      </div></fieldset>
      <p class="muted">Dental cleaning starts at $280, not a final total.
      An exact quote must be supplied and accepted before booking.</p>`;
  }

  if (state.step === 1) {
    const eligible = Object.keys(vets).filter(vet =>
      qualifies(vet, state.service) && vets[vet].includes(DAY)
    );
    const countText = vet => {
      const count = matching(vet).length;
      return `${count} bookable ${count === 1 ? "time" : "times"} in the supplied Thursday data`;
    };
    body = `<p class="muted">“Any” shows all eligible vets together.
      Picking a time assigns the named vet.</p>
      <fieldset><legend>Vet preference</legend><div class="options">
      ${radio("vet", "any", state.vet === "any", "Any available vet",
        countText("any") +
        (services[state.service].restricted ? " · Dr. Mary Major only" : ""))}
      ${eligible.map(vet => radio("vet", vet, state.vet === vet,
        `Dr. ${vet}`, countText(vet))).join("")}
      </div></fieldset>`;
  }

  if (state.step === 2) {
    const available = matching().sort((a, b) => a.start.localeCompare(b.start));
    body = `<p><strong>Thursday, October 15, 2026</strong><br>
      <span class="muted">Demo date · clinic-local time · 24-hour clock</span></p>`;
    body += available.length ?
      `<fieldset><legend>Available appointment times</legend>
      <div class="options times">
      ${available.map(slot => radio("slot", slot.id, state.slot === slot.id,
        range(slot), `Dr. ${slot.vet}`)).join("")}
      </div></fieldset>` :
      `<div class="notice"><strong>No bookable times in the supplied data.</strong>
      <p>Go back to change your vet or service.
      Other dates are not included in this demo. This does not mean
      the clinic is fully booked.</p></div>`;
    body += `<p class="muted">Hours: 09:00–17:00.
      Closed for lunch 12:00–13:00. The full visit must fit within opening hours.</p>`;
  }

  if (state.step === 3) {
    body = `<p>Check the appointment below before confirming.</p>
      <div class="edits" aria-label="Edit appointment">
        <button type="button" data-edit="0">Edit service</button>
        <button type="button" data-edit="1">Edit vet</button>
        <button type="button" data-edit="2">Edit time</button>
      </div>`;
    if (services[state.service].estimate) {
      body += `<p class="notice">Booking is blocked until the clinic supplies
        an exact total for you to accept. “From $280” is not a final price.</p>`;
    }
  }

  if (state.step === 4) {
    body = `<p>This is a prototype confirmation only.
      No appointment was sent to the clinic.</p>`;
  }

  $("screen").innerHTML =
    `<h2 id="step-title" tabindex="-1">${titles[state.step]}</h2>${body}`;

  document.querySelectorAll(".progress li").forEach((item, index) => {
    item.removeAttribute("aria-current");
    if (index === Math.min(state.step, 3))
      item.setAttribute("aria-current", "step");
  });
  $("back").hidden = state.step === 0;
  $("actions").hidden = state.step === 4;
  $("next").textContent = [
    "Continue to vet", "Continue to times", "Review appointment",
    "Confirm demo booking", ""
  ][state.step];
  sync();
  if (focus) $("step-title").focus();
}

$("booking").addEventListener("change", event => {
  const input = event.target;
  if (input.name === "service") {
    state.service = input.value;
    state.vet = "any";
    state.slot = "";
  } else if (input.name === "vet") {
    state.vet = input.value;
    state.slot = "";
  } else if (input.name === "slot") {
    state.slot = input.value;
  }
  // Do not re-render radios: preserve keyboard and screen-reader focus.
  sync(true);
});

$("back").addEventListener("click", () => {
  state.step--;
  render();
});
$("booking").addEventListener("click", event => {
  const edit = event.target.closest("[data-edit]");
  if (!edit) return;
  state.step = Number(edit.dataset.edit);
  render();
});
$("booking").addEventListener("submit", event => {
  event.preventDefault();
  if (!canContinue()) return;
  // Local rule recheck only. Production must atomically revalidate and
  // reserve on the server before displaying a real confirmation.
  state.step++;
  render();
});
render(false);
</script>
</body>
</html>
