      const start = toMinutes(slot.start), end = start + service.duration;
      return intervals.some(([open, close]) => start >= open && end <= close);
    });

    function slotsFor(service) {
      return bookable.filter(s => s.service === service &&
        (!vetChoice || vetChoice === "any" || s.vet === vetChoice));
    }

    function canGo(target) {
      return target === 0 || (!!serviceName && target === 1) ||
        (!!serviceName && !!vetChoice && target === 2) ||
        (!!serviceName && !!vetChoice && !!chosenSlot && target === 3);
    }

    function render() {
      const labels = ["Service", "Vet", "Time", "Confirm"];
      document.getElementById("steps").innerHTML = labels.map((label, i) =>
        `<button class="step" type="button" data-step="${i}" ${canGo(i) ? "" : "disabled"}
          ${step === i ? 'aria-current="step"' : ""}>${i + 1}. ${label}</button>`
      ).join("");

      document.getElementById("summary").innerHTML = `
        <p><strong>Service:</strong> ${serviceName || "Not selected"}</p>
        <p><strong>Vet:</strong> ${chosenSlot ? "Dr. " + chosenSlot.vet :
          (vetChoice === "any" ? "Any available vet" : (vetChoice || "Not selected"))}</p>
        <p><strong>Time:</strong> ${chosenSlot ? `${day}, ${fmtTime(chosenSlot.start)}` : "Not selected"}</p>
        <p><strong>Price:</strong> ${serviceName ? serviceFor(serviceName).price : "Not selected"}</p>`;

      const panel = document.getElementById("panel");
      if (step === 0) {
        panel.innerHTML = `<h2>Choose a service</h2>
          <p class="hint">Popular services are listed first. Prices are shown before you continue.</p>
          <div class="card-list">${services.map(s => {
            const count = bookable.filter(x => x.service === s.name).length;
            return `<button class="choice service-choice" type="button" data-service="${s.name}"
              aria-pressed="${serviceName === s.name}">
              ${s.popular ? '<span class="badge">Popular</span>' : ""}
              <strong>${s.name}</strong>
              <small>${s.duration} min · ${s.price} · ${
                count ? `${count} bookable Thursday ${count === 1 ? "time" : "times"}` :
                "No bookable times in the supplied Thursday availability"
              }</small>
            </button>`;
          }).join("")}</div>`;
      } else if (step === 1) {
        const svc = serviceFor(serviceName);
        const anyCount = bookable.filter(s => s.service === serviceName).length;
        panel.innerHTML = `<h2>Choose a vet</h2>
          <p class="hint">You can choose a specific vet or let us match you with any available vet.</p>
          <div class="card-list">
            <button class="choice vet-choice" type="button" data-vet="any" aria-pressed="${vetChoice === "any"}">
              <strong>Any available vet</strong><small>${anyCount} bookable Thursday ${anyCount === 1 ? "time" : "times"}</small>
            </button>
            ${vets.map(v => {
              const count = bookable.filter(s => s.service === serviceName &&
                s.vet === v.name.replace("Dr. ", "")).length;
              const canDo = eligible(svc, v);
              const unavailable = !canDo ? "Does not perform this service" :
                !count ? "No bookable times in the supplied availability" :
                `${count} bookable ${count === 1 ? "time" : "times"}`;
              return `<button class="choice vet-choice" type="button" data-vet="${v.name.replace("Dr. ", "")}"
                aria-pressed="${vetChoice === v.name.replace("Dr. ", "")}" ${!canDo || !count ? "disabled" : ""}>
                <strong>${v.name}</strong><small>${unavailable}</small>
              </button>`;
            }).join("")}
          </div>`;
      } else if (step === 2) {
        const available = slotsFor(serviceName);
        panel.innerHTML = `<h2>Choose a time</h2>
          <p class="hint">${day} · Clinic hours 9:00 AM–5:00 PM; closed 12:00–1:00 PM.</p>
          ${available.length ? `<div class="card-list">${available.map((s, i) => `
            <button class="choice slot-choice" type="button" data-slot="${i}"
              aria-pressed="${chosenSlot === s}">
              <strong>${fmtTime(s.start)}</strong>
              <small>Dr. ${s.vet} · ${serviceFor(s.service).duration} min</small>
            </button>`).join("")}</div>` :
            `<div class="notice">No bookable times are available for this selection in the supplied Thursday data. Choose another service or go back. Times that conflict with clinic hours, lunch, or vet eligibility are not offered.</div>`}
          <p class="hint">The availability data gives a weekday, but not the calendar date. A real booking needs the exact date.</p>`;
      } else {
        const actualVet = chosenSlot ? "Dr. " + chosenSlot.vet : "";
        panel.innerHTML = `<h2>${demoConfirmed ? "Demo confirmation" : "Review and confirm"}</h2>
          <div class="review"><dl>
            <dt>Date</dt><dd>${day} — exact calendar date not supplied</dd>
            <dt>Time</dt><dd>${fmtTime(chosenSlot.start)}</dd>
            <dt>Vet</dt><dd>${actualVet}</dd>
            <dt>Service</dt><dd>${serviceName} · ${serviceFor(serviceName).duration} min</dd>
            <dt>Price</dt><dd>${serviceFor(serviceName).price}</dd>
            <dt>Clinic</dt><dd>Harbor Street Veterinary Clinic<br>12 Harbor Street, Example City</dd>
          </dl></div>
          ${serviceFor(serviceName).price.startsWith("from") ?
            `<div class="notice">This is a starting price, not a final quote. The clinic must provide and get your agreement to an estimate before a real booking is confirmed.</div>` : ""}
          <div class="notice" role="status">${demoConfirmed ?
            "Demo only: no appointment was sent or booked. The exact calendar date is missing from the supplied data." :
            "Review all details above. The prototype cannot create a real booking until the availability API supplies the exact calendar date."}</div>`;
      }

      document.getElementById("actions").innerHTML = `
        <button class="secondary" type="button" id="back" ${step === 0 ? "disabled" : ""}>Back</button>
        ${step < 3
          ? `<button class="primary" type="button" id="next" ${!canGo(step + 1) ? "disabled" : ""}>Continue</button>`
          : `<button class="primary" type="button" id="confirm" ${demoConfirmed ? "disabled" : ""}>Confirm appointment (demo)</button>`}`;

      document.querySelectorAll("[data-step]").forEach(b => b.addEventListener("click", () => {
        const target = Number(b.dataset.step);
        if (canGo(target)) { step = target; render(); }
      }));
      document.querySelectorAll(".service-choice").forEach(b => b.addEventListener("click", () => {
        serviceName = b.dataset.service; vetChoice = "any"; chosenSlot = null; demoConfirmed = false; render();
      }));
      document.querySelectorAll(".vet-choice").forEach(b => b.addEventListener("click", () => {
        if (b.disabled) return;
        vetChoice = b.dataset.vet; chosenSlot = null; demoConfirmed = false; render();
      }));
      document.querySelectorAll(".slot-choice").forEach(b => b.addEventListener("click", () => {
        chosenSlot = slotsFor(serviceName)[Number(b.dataset.slot)]; demoConfirmed = false; render();
      }));
      document.getElementById("back").addEventListener("click", () => {
        if (step > 0) { step--; demoConfirmed = false; render(); }
      });
      const next = document.getElementById("next");
      if (next) next.addEventListener("click", () => {
        if (canGo(step + 1)) { step++; render(); }
      });
      const confirm = document.getElementById("confirm");
      if (confirm) confirm.addEventListener("click", () => { demoConfirmed = true; render(); });
    }
    render();
  </script>
</body>
</html>
```

## Design rationale

- **Separate steps, with a persistent summary.** Service → vet → time → confirm keeps each decision focused on a 375 px screen. The summary updates as selections change, so owners can check the service, assigned vet, time, and price throughout. Wellness exams and vaccinations appear first and are marked popular.
- **“Any available vet”** is a selectable option. Once a time is chosen, the summary names the vet actually assigned to that slot.
- **“From $280” stays explicit.** The prototype labels it as a starting price, not a quote. A real dental booking should require an estimate and owner agreement before confirmation, rather than imply that $280 is the final price.
- **Accessibility departure:** white text on `#7FD1AE` does not meet WCAG AA contrast. Primary buttons keep the requested mint background but use ink (`#1D2B33`) labels instead. Focus indicators and disabled states are also visible.

## Data problems and handling

- **Several returned slots are not bookable:** Richard’s exotic-pet slot conflicts with the service’s vet restriction; the 11:30 dental slot overlaps lunch; the 12:30 wellness slot is during lunch; and the 4:45 wellness slot ends after closing. The UI filters these out and only offers Mary’s 11:00 exotic check-up and Richard’s 2:00 wellness exam.
- **No vaccination slot is returned**, and no valid dental slot remains. The UI explains when a service has no bookable Thursday times. The API should return current valid availability or an explicit no-availability result.
- **The API provides only “Thursday,” not a calendar date.** The prototype displays that limitation and does not pretend a real booking was made. Production confirmation should be blocked until an exact date is supplied.
- **Dental has a starting price, not a final price.** Obtain a quote and owner approval before confirming; do not present “from $280” as a guaranteed total.
- **Availability may become stale.** The API should include a date and timezone and support rechecking or holding a slot at confirmation to prevent booking a time that has just been taken.

